entries[154166] = { ["name"] = "Rauer Lederharnisch", ["text"] = "Benutzen: Verhindert 2 Stunden lang, dass der Spielercharakter beim Reiten in Kul Tiras und Zandalar benommen wird.\n\nDie Dauer ist für Lederverarbeiter vervierfacht.\nVerkaufspreis:" }
entries[154167] = { ["name"] = "Trommeln des Mahlstroms", ["text"] = "Benutzen: Erhöht das Tempo aller Gruppen- und Schlachtzugsmitglieder um 15%. Hält 40 Sek. lang an.\n\nWenn der Effekt endet, sind die Betroffenen erschöpft und können 10 Min. lang nicht mehr von 'Kampfrausch', 'Heldentum' oder 'Zeitkrümmung' profitieren.\n\nWirkt nicht bei Verbündeten über Stufe 50. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[154168] = { ["name"] = "Schimmerschuppentauchanzug", ["text"] = "Benutzen: Legt einen Taucheranzug an, der Eure Schwimmgeschwindigkeit um 100% erhöht. Hält 15 Min. lang an." }
entries[154169] = { ["name"] = "Schimmerschuppentauchhelm", ["text"] = "Benutzen: Legt einen Taucherhelm an, der Euch unter Wasser atmen lässt. Hält 15 Min. lang an." }
entries[154170] = { ["name"] = "RE-USE ME", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Lederverarbeitung von Kul Tiras (150)" }
entries[154171] = { ["name"] = "Feurige Essenz", ["text"] = "Questgegenstand" }
entries[154172] = { ["name"] = "Aman'thuls Vision", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Tempowertung um + 6.\n+ 6 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 6.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Geschwindigkeit, Eure Vermeidung und Euren Lebensraub 12 Sek. lang um 9 zu erhöhen.\n\nAman'thuls Pracht\nWenn Euch das Pantheon Macht verleiht, wird Eure Intelligenz 15 Sek. lang um 6 erhöht.\nVerkaufspreis:" }
entries[154173] = { ["name"] = "Aggramars Überzeugung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Erlittener Schaden hat eine Chance, Eure Vielseitigkeit 14 Sek. lang um 27 zu erhöhen.\n\nAggramars Seelenstärke\nWenn Euch das Pantheon Macht verleiht, wird Eure maximale Gesundheit 15 Sek. lang um 94 erhöht und Ihr werdet um 988 Gesundheit geheilt.\nVerkaufspreis:" }
entries[154174] = { ["name"] = "Golganneths Lebenskraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 10 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\nWenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 5 ] Naturschaden zufügt. Hält 15 Sek. lang an.\nVerkaufspreis:" }
entries[154175] = { ["name"] = "Eonars Mitgefühl", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Heileffekte haben eine Chance, in der Nähe eine Smaragdblüte wachsen zu lassen, die einen zufälligen verletzten Verbündeten alle 2 Sek. um 16 Gesundheit heilt. Hält 12 Sek. lang an.\n\nEonars tiefgrüne Umarmung\nWenn Euch das Pantheon Macht verleiht, gewähren Eure nächsten 4 Einsätze von direkter Heilung dem Ziel einen Schild, der 30 Sek. lang 24 Schaden verhindert.\nVerkaufspreis:" }
entries[154176] = { ["name"] = "Khaz'goroths Kühnheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\n+6 Stärke\nAnlegen: Eure Schaden verursachenden Angriffe haben eine Chance, Eure Waffe durch die Flammen von Khaz'goroths Schmiede 12 Sek. lang erglühen zu lassen, wodurch Eure automatischen Angriffe zusätzlich ( 1 * Haupthandwaffen-Min-Grundgeschwindigkeit * 8 ) Feuerschaden verursachen.\n\nKhaz'goroths Schmiedeschlag\nWenn Euch das Pantheon Macht verleiht, wird Euer kritischer Trefferwert, Euer Tempo, Eure Meisterschaft oder Eure Vielseitigkeit 15 Sek. lang um 26 erhöht. Khaz'goroth erhöht immer Euren höchsten Wert.\nVerkaufspreis:" }
entries[154177] = { ["name"] = "Norgannons Heldenmut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Pfad der Titanen (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 8.\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, Eure Intelligenz 12 Sek. lang um 22 zu erhöhen.\n\nNorgannons Befehl\nWenn Euch das Pantheon Macht verleiht, erhaltet Ihr 15 Sek. lang 6 Aufladungen von 'Norgannons Befehl'. Eure Schaden verursachenden Zauber verbrauchen eine Aufladung, um dem Ziel zusätzlich 13 Schaden durch eine zufällige Magieart zuzufügen.\nVerkaufspreis:" }
