entries[154704] = { ["name"] = "Schriftrolle des Suchens", ["text"] = "Questgegenstand\nBenutzen: Wir suchen die Sucher. (10 Sek. Abklingzeit)\n\"Findet, was Ihr sucht. Benutzt sie, sooft Ihr möchtet. Achtet darauf, genug Sonne abzubekommen.\"" }
entries[154705] = { ["name"] = "Schlachtflagge: Ansporn", ["text"] = "Benutzen: Macht eine Schlachtenflagge an Eurem Rücken fest, die für 15 Sek. Eure Reitgeschwindigkeit und die Eurer Gruppenmitglieder innerhalb von 10 Metern um 15% erhöht.\n\nKann nur beritten eingesetzt werden.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)" }
entries[154706] = { ["name"] = "Schlachtflagge: Phalanxverteidigung", ["text"] = "Benutzen: Stellt eine Flagge auf dem Schlachtfeld auf, die den erlittenen Schaden von Verbündeten innerhalb von 15 Metern um 15% verringert. Hält 30 Sek. lang an.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)" }
entries[154707] = { ["name"] = "Schlachtflagge: Geist der Freiheit", ["text"] = "Benutzen: Stellt eine Flagge auf dem Schlachtfeld auf, die die Dauer von Kontrollverlusteffekten bei Verbündeten innerhalb von 15 Metern verringert. Hält 30 Sek. lang an.\n\nKann nur in Kul Tiras, Zandalar und ungewerteten Schlachtfeldern eingesetzt werden. (5 Min Abklingzeit)" }
