entries[155819] = { ["name"] = "Dreimal eingelegtes Dreschadonomelett", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört Hubert, der Euch 10 Min. lang beschützt.\n\nNur im Sturmsangtal.\n\"Huberts Lieblingsmahlzeit. Die gibt dem Hündchen richtig Kraft.\"" }
entries[155820] = { ["name"] = "Stachelbombe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Wirft einen mit Stacheleberstacheln gespickten Sprengsatz, der allen Gegnern innerhalb von 10 Metern 3775 körperlichen Schaden zufügt und sie für 3 Sek. betäubt. (2 Min Abklingzeit)\n\"Randvoll mit Stacheleberstacheln.\"" }
entries[155821] = { ["name"] = "Phiole mit zähflüssigem Schleim", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bedeckt Euch mit zähflüssigem Schleim, der den Effekt von 'Pfählstacheln' der Klingenstacheleber abschwächt.\n\"Honig in einer Mischung mit Salben und Ölen. Riecht jedoch noch immer süß!\"" }
