entries[155823] = { ["name"] = "Eisiger Schneeball", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Werft mich! (30 Sek. Abklingzeit)\n\"Schneeballschlacht!\"" }
